#define _CRT_SECURE_NO_WARNINGS
#include <assert.h>
#include <stdio.h>
#include "../src/part_command.h"
int main(void){
    const wchar_t *valid[]={
        L"REFERENCES PRT1",L"REFERENCES PRT1 SURFACE:2",L"REFERENCES PRT1 EDGE:71",
        L"DATUM_PLANE PRT1 DTM1 PLANE:TOP -25",L"DATUM_AXIS PRT1 A1 PLANES TOP RIGHT",L"DATUM_AXIS PRT1 A1 CYLINDER SURFACE:70",
        L"DATUM_POINT PRT1 P1 CSYS:PRT_CSYS 1 2 3",L"DATUM_CSYS PRT1 C1 CSYS:PRT_CSYS 1 2 3 90 0 -45",L"DATUM_CURVE PRT1 L1 CSYS:PRT_CSYS 0 0 0 10 20 30",
        L"SKETCH_BEGIN PRT1 SK1 TOP RIGHT",L"SKETCH_CREATE PRT1 SK1 TOP RIGHT RECT -40 -30 80 60",L"SKETCH_CREATE PRT1 SK1 TOP RIGHT CIRCLE 0 0 5",L"SKETCH_CREATE PRT1 SK1 TOP RIGHT LINE 0 0 20 20",L"SKETCH_CREATE PRT1 SK1 TOP RIGHT ARC 0 0 10 0 90",
        L"SKETCH_ADD PRT1 SK1 LINE 0 0 10 10",L"SKETCH_ADD PRT1 SK1 CENTERLINE 0 0 10 0",L"SKETCH_INFO PRT1 SK1",
        L"SKETCH_DIM PRT1 SK1 LENGTH 0 NONE 20",L"SKETCH_DIM PRT1 SK1 RADIUS 0 NONE 20",L"SKETCH_DIM PRT1 SK1 DIAMETER 0 NONE 20",L"SKETCH_DIM PRT1 SK1 ANGLE 0 1 45",L"SKETCH_DIM PRT1 SK1 DISTANCE 0:START 0:END 10",L"SKETCH_DIM PRT1 SK1 DISTANCE_X 0:CENTER 1:CENTER 30",L"SKETCH_DIM PRT1 SK1 DISTANCE_Y 0:END 1:START 5",
        L"SKETCH_CONSTRAINT PRT1 SK1 HORIZONTAL 0",L"SKETCH_CONSTRAINT PRT1 SK1 VERTICAL 0",L"SKETCH_CONSTRAINT PRT1 SK1 COINCIDENT 0:END 1:START",L"SKETCH_CONSTRAINT PRT1 SK1 PARALLEL 0 1",L"SKETCH_CONSTRAINT PRT1 SK1 PERPENDICULAR 0 1",L"SKETCH_CONSTRAINT PRT1 SK1 TANGENT 0 1",L"SKETCH_CONSTRAINT PRT1 SK1 EQUAL_LENGTH 0 1",L"SKETCH_CONSTRAINT PRT1 SK1 EQUAL_RADIUS 0 1",L"SKETCH_CONSTRAINT PRT1 SK1 SYMMETRY 0:START 1:START 2"
    };
    const wchar_t *invalid[]={
        L"DATUM_PLANE PRT1 DTM1 TOP nan",L"DATUM_PLANE PRT1 DTM1 TOP 0",L"DATUM_POINT PRT1 P1 C1 0 1",L"DATUM_CSYS PRT1 C1 C0 0 0 0 361 0 0",L"DATUM_CURVE PRT1 L1 C0 1 2 3 1 2 3",L"DATUM_AXIS PRT1 A1 PLANES TOP TOP",L"REFERENCES PRT1 SURFACE:-1",L"DATUM_POINT PRT1 ../p C0 1 2 3",L"SKETCH_CREATE PRT1 SK1 TOP RIGHT RECT 0 0 -1 10",L"SKETCH_ADD PRT1 SK1 LINE 0 0 0 0",L"SKETCH_ADD PRT1 SK1 ARC 0 0 5 0 360",L"SKETCH_DIM PRT1 SK1 LENGTH 0 NONE inf",L"SKETCH_DIM PRT1 SK1 ANGLE 0 1 361",L"SKETCH_DIM PRT1 SK1 DISTANCE 0 0 10",L"SKETCH_DIM PRT1 SK1 LENGTH 0 1 10",L"SKETCH_CONSTRAINT PRT1 SK1 HORIZONTAL 0 1",L"SKETCH_CONSTRAINT PRT1 SK1 SYMMETRY 0 1",L"SKETCH_CONSTRAINT PRT1 SK1 TANGENT 0:BAD 1"
    };
    wchar_t protocol[1024];PartCommand cmd;int i;
    for(i=0;i<sizeof(valid)/sizeof(valid[0]);i++){swprintf_s(protocol,1024,L"CREO_OP %ls",valid[i]);assert(part_command_parse(protocol,&cmd)==1&&cmd.verb==PART_FOUNDATION);}
    for(i=0;i<sizeof(invalid)/sizeof(invalid[0]);i++){swprintf_s(protocol,1024,L"CREO_OP %ls",invalid[i]);assert(part_command_parse(protocol,&cmd)==-1&&cmd.verb==PART_NONE);}
    assert(part_command_parse(L"CREO_OP REFERENCES PRT1\nCREO_OP DATUM_PLANE PRT1 P1 TOP 5",&cmd)==-1);
    assert(part_command_parse(L"CREO_OP SKETCH_ADD PRT1 SK1 CIRCLE 0 0 5\nCREO_PLAN EMPTY_SOLID",&cmd)==-1);
    printf("foundation protocol: %d valid + %d invalid + 2 mixed-command cases passed\n",(int)(sizeof(valid)/sizeof(valid[0])),(int)(sizeof(invalid)/sizeof(invalid[0])));return 0;
}
